145				content: "\2197";
146				content: "\2197" / "";
147				display: inline-block;
148				margin-inline-start: 0.2em;
149				font-size: 0.8em;
150				text-decoration: none;
151			}
152			button,
153			.button {
154				display: inline-block;
155				text-decoration: none;
156				padding: 0.75rem 1.5rem;
157				font-size: 1rem;
158				font-weight: 500;
159				font-family: inherit;
160				color: var(--background);
161				background: var(--accent);
162				border: 2px solid var(--accent);
