212				padding-block: 1.5rem 0;
213			}
214			nav ul {
215				display: flex;
216				flex-wrap: wrap;
217				gap: 0.5rem 1.5rem;
218				margin: 1rem 0 0 0;
219				padding: 0;
220				list-style: none;
221			}
222			nav li {
223				margin: 0;
224			}
225			footer nav ul {
226				justify-content: center;
227				margin: 0 0 1rem 0;
228			}
229			main {
230				padding: 1rem 0;
231			}
232			main:focus {
233				outline: none;
234			}
235			section {
236				margin: 2rem 0;
237			}
