308				font-size: 0.875em;
309			}
310			.field {
311				margin-bottom: 1rem;
312			}
313			label {
314				display: block;
315				margin-bottom: 0.5rem;
316				font-weight: 500;
317			}
318			input,
319			textarea {
320				width: 100%;
321				padding: 0.5rem;
322				font: inherit;
323				color: var(--text);
324				background: var(--surface);
325				border: 1px solid var(--border-control);
326				border-radius: 0.25rem;
327			}
328			textarea {
329				resize: vertical;
