335				margin-top: 1rem;
336				padding: 0.75rem 1rem;
337				border-radius: 0.25rem;
338				background: var(--surface);
339				background: color-mix(in srgb, var(--success) 10%, transparent);
340				color: var(--success);
341				border: 1px solid var(--success);
342			}
343			.form-hint {
344				margin: 0 0 1rem 0;
345				font-size: 0.875rem;
346				color: var(--text-secondary);
347			}
