441		<header id="top">
442			<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem;">
443				<h1 style="margin: 0;">Welcome</h1>
444				<button id="theme-toggle" type="button" aria-label="Toggle dark mode" title="Toggle dark mode" style="padding: 0.5rem; border: none; background: var(--surface); color: var(--text); cursor: pointer; font-size: 1.25rem; display: flex; align-items: center; justify-content: center; width: 2.5rem; height: 2.5rem; border-radius: 0.25rem;">🌙</button>
445			</div>
