548								<th scope="col" style="padding: 0.5rem; text-align: center;">Chrome</th>
549								<th scope="col" style="padding: 0.5rem; text-align: center;">Firefox</th>
550								<th scope="col" style="padding: 0.5rem; text-align: center;">Safari</th>
551							</tr>
552						</thead>
