555								<th scope="row" style="padding: 0.5rem; text-align: left;">CSS Grid</th>
556								<td style="padding: 0.5rem; text-align: center;">✓</td>
557								<td style="padding: 0.5rem; text-align: center;">✓</td>
558								<td style="padding: 0.5rem; text-align: center;">✓</td>
559							</tr>
560							<tr style="border-bottom: 1px solid var(--border);">
561								<th scope="row" style="padding: 0.5rem; text-align: left;">CSS Variables</th>
562								<td style="padding: 0.5rem; text-align: center;">✓</td>
563								<td style="padding: 0.5rem; text-align: center;">✓</td>
564								<td style="padding: 0.5rem; text-align: center;">✓</td>
565							</tr>
