567								<th scope="row" style="padding: 0.5rem; text-align: left;">Aspect Ratio</th>
568								<td style="padding: 0.5rem; text-align: center;">✓</td>
569								<td style="padding: 0.5rem; text-align: center;">✓</td>
570								<td style="padding: 0.5rem; text-align: center;">✓</td>
571							</tr>
572						</tbody>
573					</table>
574				</article>
